[meta]
name = Herran's Laboratory
ambient = 0.22 0.26 0.22
fog = 0.03 0.05 0.03
fog_range = 6 34
torch = 5 0.85 0.95 0.7
start = 16 2 90
default = v
entity_floor = auto
edge_top = 8
edge_tex = lab_stone

// Herran's laboratory, hewn out of the Hollow Peak under his castle, behind the false wall in his
// library: where he sewed beasts and men into many-armed things before he did it to himself. The
// hidden stair comes down into the vat cellar, where his failures hang in green fluid and the
// Handcrawlers lie still among the vats; west of it the dissecting rooms, east the menagerie's pens and
// their cages, and south down the ossuary of hands, his own laboratory, deepest of all, with three
// pages of his journal, his cleaver, and a stair that climbs back up to the Great Hall (`oneway`).
// It is dark: no tile here keeps less than 0.6 of it.

[legend]
// The peak's rock, faced in rubble.
# = wall tex=lab_stone top=8 cap=lab_stone
// The foot of the hidden stair.
f = floor tex=lab_floor h=0 ceil=4 ceil_tex=lab_stone side=lab_stone dark=0.65
// The vat cellar.
v = floor tex=lab_floor h=0 ceil=5 ceil_tex=lab_stone side=lab_stone dark=0.6
// The dissecting rooms, the menagerie's pens and the ossuary of hands, darker still.
r = floor tex=lab_floor h=0 ceil=4.5 ceil_tex=lab_stone side=lab_stone dark=0.7
n = floor tex=lab_floor h=0 ceil=5 ceil_tex=lab_stone side=lab_stone dark=0.7
o = floor tex=lab_floor h=0 ceil=4 ceil_tex=lab_stone side=lab_stone dark=0.75
// Herran's own laboratory.
p = floor tex=lab_floor h=0 ceil=5.5 ceil_tex=lab_stone side=lab_stone dark=0.6

