[entities]
// The hidden stair back up to the castle's library, and the stair at the far end that climbs to the
// Great Hall: once taken, it leaves you there.
A = exit map=herrans_castle at=10,10,-90 label=Climb_back_up model=sunken_stair yaw=90 on=f
Z = exit map=herrans_castle at=21,22,-90 label=Climb_the_hidden_stair model=sunken_stair yaw=-90 oneway on=p
// Lights: what little there is, green from the vats and cold from a few lamps.
L = light y=3 color=0.5,0.8,0.5 radius=6
N = light y=3 color=0.7,0.7,0.6 radius=5
V = vat
T = dissecting_table
G = specimen_cage
R = hand_rack
E = lab_bench
// What he made.
C = handcrawler
M = amalgam
// Finds: a salve in the dissecting rooms, a draught in the pens, and on his own bench his cleaver.
B = chest item=clotting_salve count=3 gold=160 model=coffer
D = chest item=ember_draught count=2 gold=180 model=banded
F = chest item=hearth_ash count=1 gold=200 model=coffer
H = chest item=surgeons_cleaver gold=250 model=banded
// Three pages of his journal.
I = hint text="A hound, an ape, a man. They took to each other|better than I dared hope. They took to me less."
J = hint text="The hands I did not need I hung in the hall.|I could not bear to burn them. They were Mother's gift."
